import { sanitizeAndSerializeProviderData } from "wasp/server/auth";
import type { PrismaClient } from "@prisma/client";

export const seedData = async (prisma: PrismaClient) => {
  const usersToSeed = [
    { username: "manager", password: "password123", role: "MANAGER" },
    { username: "agent1", password: "password123", role: "AGENT" },
    { username: "agent2", password: "password123", role: "AGENT" },
    { username: "customer1", password: "password123", role: "CUSTOMER" },
  ];

  for (const user of usersToSeed) {
    const existing = await prisma.user.findUnique({
      where: { username: user.username },
    });
    if (existing) continue;

    const providerData = await sanitizeAndSerializeProviderData({
      hashedPassword: user.password,
    });

    await prisma.user.create({
      data: {
        username: user.username,
        password: user.password,
        role: user.role,
        auth: {
          create: {
            identities: {
              create: {
                providerName: "username",
                providerUserId: user.username,
                providerData: providerData,
              },
            },
          },
        },
      },
    });
  }
};

import { app, page, route, query, action } from "@wasp.sh/spec";
import { MainPage } from "./src/MainPage" with { type: "ref" };
import { LoginPage } from "./src/LoginPage" with { type: "ref" };
import { SignupPage } from "./src/SignupPage" with { type: "ref" };
import { userSignupFields } from "./src/auth/signup" with { type: "ref" };
import { getTickets, getAgents } from "./src/queries" with { type: "ref" };
import { createTicket, simulateSlaBreach } from "./src/actions" with { type: "ref" };
import { seedData } from "./src/dbSeeds" with { type: "ref" };

export default app({
  name: "app",
  title: "app",
  wasp: { version: "^0.24.0" },
  head: ["<link rel='icon' href='/favicon.ico' />"],
  auth: {
    userEntity: "User",
    methods: {
      usernameAndPassword: {
        userSignupFields,
      },
    },
    onAuthFailedRedirectTo: "/login",
  },
  db: {
    seeds: [seedData],
  },
  spec: [
    route("RootRoute", "/", page(MainPage, { authRequired: true })),
    route("LoginRoute", "/login", page(LoginPage)),
    route("SignupRoute", "/signup", page(SignupPage)),
    query(getTickets, { entities: ["Ticket", "User"] }),
    query(getAgents, { entities: ["User", "Ticket"] }),
    action(createTicket, { entities: ["Ticket", "User"] }),
    action(simulateSlaBreach, { entities: ["Ticket", "User"] }),
  ],
});

import { LoginForm } from "wasp/client/auth";

export function LoginPage() {
  return (
    <div style={{ display: "flex", justifyContent: "center", alignItems: "center", height: "100vh" }}>
      <LoginForm />
    </div>
  );
}

import { SignupForm } from "wasp/client/auth";

export function SignupPage() {
